WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT id, page, event_time, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM gaps), valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time FROM sessions_web_events WHERE page IS NOT NULL), enriched AS (SELECT id, session_id_2, LEAD(days_since_event_time, 2) OVER (PARTITION BY page ORDER BY event_time, id) AS next_days_since_event_time, SUM(session_id_2) OVER (PARTITION BY page ORDER BY days_since_event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_session_id_2 FROM valid), valid_web_events AS (SELECT *, ROUND(cumulative_session_id_2, 0) AS cumulative_session_id_2_rounded FROM enriched WHERE cumulative_session_id_2 IS NOT NULL), metrics AS (SELECT id, session_id_2, ROW_NUMBER() OVER (ORDER BY cumulative_session_id_2, id) AS row_seq, ROW_NUMBER() OVER (ORDER BY session_id_2, id) AS event_seq, NTILE(5) OVER (ORDER BY cumulative_session_id_2_rounded DESC, id) AS cumulative_session_id_2_rounded_bucket, DENSE_RANK() OVER (ORDER BY cumulative_session_id_2_rounded NULLS FIRST) AS cumulative_session_id_2_rounded_dense_rank FROM valid_web_events), scored AS (SELECT *, ROW_NUMBER() OVER (ORDER BY event_seq, id) AS seq_no, LEAD(cumulative_session_id_2_rounded_dense_rank, 1) OVER (ORDER BY cumulative_session_id_2_rounded_bucket, id) AS next_cumulative_session_id_2_rounded_dense_rank FROM metrics WHERE cumulative_session_id_2_rounded_bucket = 4), report AS (SELECT id, row_seq, event_seq, cumulative_session_id_2_rounded_bucket, seq_no FROM scored) SELECT id, row_seq, event_seq, cumulative_session_id_2_rounded_bucket, seq_no FROM report ORDER BY id DESC
